import { useId, useLayoutEffect, useRef, type ReactNode } from 'react';
import { focusables } from '../../../primitives/focus';
import type { Align, Side } from '../../../primitives/place';
import { useControllableState } from '../../../primitives/use-controllable-state';
import { useDismiss } from '../../../primitives/use-dismiss';
import { usePlacement } from '../../../primitives/use-placement';
import { usePopover } from '../../../primitives/use-popover';
import { Button, type ButtonProps } from '../../actions/button/Button';
import './popover.css';

export interface PopoverProps {
  /** The trigger button's label. */
  label: ReactNode;
  /** Extra props for the trigger button, such as `variant` or `icon`. */
  triggerProps?: Omit<ButtonProps, 'children' | 'onClick'>;
  /** Names the popover. */
  title: ReactNode;
  children: ReactNode;
  side?: Side;
  align?: Align;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
}

/**
 * Content anchored to a button that stays visible near the viewport edge: it flips to the
 * other side when there is no room and shifts along the edge, and its arrow keeps pointing
 * at the button. A non-modal dialog in the top layer.
 */
export function Popover({
  label,
  triggerProps,
  title,
  children,
  side = 'bottom',
  align = 'center',
  open: openProp,
  defaultOpen = false,
  onOpenChange,
}: PopoverProps) {
  const [open, setOpen] = useControllableState({
    value: openProp,
    defaultValue: defaultOpen,
    onChange: onOpenChange,
  });
  const triggerRef = useRef<HTMLButtonElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const id = useId();

  usePopover(panelRef, open);
  const placement = usePlacement(triggerRef, panelRef, open, {
    side,
    align,
    offset: 12,
    padding: 12,
  });

  const close = (refocus: boolean) => {
    setOpen(false);
    if (refocus) triggerRef.current?.focus();
  };

  useDismiss({
    open,
    layerRef: panelRef,
    triggerRef,
    onDismiss: (reason) => close(reason === 'escape'),
  });

  // Move focus into the popover when it opens.
  useLayoutEffect(() => {
    if (!open || !panelRef.current) return;
    (focusables(panelRef.current)[0] ?? panelRef.current).focus({ preventScroll: true });
  }, [open]);

  return (
    <>
      <Button
        {...triggerProps}
        ref={triggerRef}
        aria-haspopup="dialog"
        aria-expanded={open}
        aria-controls={`${id}-panel`}
        onClick={() => setOpen((o) => !o)}
      >
        {label}
      </Button>
      <div
        ref={panelRef}
        id={`${id}-panel`}
        popover="manual"
        role="dialog"
        aria-labelledby={`${id}-title`}
        tabIndex={-1}
        className="atl-popover"
        data-side={placement?.side ?? side}
        style={
          placement
            ? ({
                left: placement.x,
                top: placement.y,
                '--atl-arrow': `${placement.arrow}px`,
              } as React.CSSProperties)
            : { left: 0, top: 0, opacity: 0 }
        }
      >
        <span className="atl-popover__arrow" aria-hidden="true" />
        <h3 id={`${id}-title`} className="atl-popover__title">
          {title}
        </h3>
        <div className="atl-popover__body">{children}</div>
      </div>
    </>
  );
}

@layer atlas.components {
  .atl-popover {
    position: fixed;
    inset: auto;
    width: max-content;
    max-width: min(20rem, calc(100vw - 24px));
    margin: 0;
    padding: var(--space-m);
    border: 0;
    border-radius: var(--radius-panel);
    background: var(--shoal);
    color: var(--ink);
    box-shadow: var(--elev-overlay);
    overflow: visible;
    transition:
      opacity var(--dur-step) var(--ease-anchor),
      translate var(--dur-step) var(--ease-anchor);
  }

  .atl-popover:focus-visible {
    outline: var(--focus-ring);
    outline-offset: 2px;
  }

  @starting-style {
    .atl-popover:popover-open[data-side='bottom'] {
      opacity: 0;
      translate: 0 -6px;
    }
    .atl-popover:popover-open[data-side='top'] {
      opacity: 0;
      translate: 0 6px;
    }
    .atl-popover:popover-open[data-side='left'] {
      opacity: 0;
      translate: 6px 0;
    }
    .atl-popover:popover-open[data-side='right'] {
      opacity: 0;
      translate: -6px 0;
    }
  }

  /* The arrow: a rotated square on the edge facing the anchor, at the anchor's centre. */
  .atl-popover__arrow {
    position: absolute;
    width: 12px;
    height: 12px;
    background: var(--shoal);
    rotate: 45deg;
  }

  .atl-popover[data-side='bottom'] .atl-popover__arrow {
    top: -6px;
    left: calc(var(--atl-arrow, 50%) - 6px);
    box-shadow: -1px -1px 0 color-mix(in oklch, var(--edge) 60%, transparent);
  }

  .atl-popover[data-side='top'] .atl-popover__arrow {
    bottom: -6px;
    left: calc(var(--atl-arrow, 50%) - 6px);
    box-shadow: 1px 1px 0 color-mix(in oklch, var(--edge) 60%, transparent);
  }

  .atl-popover[data-side='left'] .atl-popover__arrow {
    right: -6px;
    top: calc(var(--atl-arrow, 50%) - 6px);
    box-shadow: 1px -1px 0 color-mix(in oklch, var(--edge) 60%, transparent);
  }

  .atl-popover[data-side='right'] .atl-popover__arrow {
    left: -6px;
    top: calc(var(--atl-arrow, 50%) - 6px);
    box-shadow: -1px 1px 0 color-mix(in oklch, var(--edge) 60%, transparent);
  }

  .atl-popover__title {
    margin-bottom: var(--space-2xs);
    font-size: var(--step-0);
    font-weight: 650;
  }

  .atl-popover__body {
    font-family: var(--font-prose);
    line-height: var(--leading-prose);
  }

  @media (forced-colors: active) {
    .atl-popover {
      border: 1px solid CanvasText;
    }
  }
}
